-- Expand UniEco's public tertiary directory with GTEC-listed Colleges of Education and health training colleges.
-- Roster and active statuses were checked against GTEC institution-specific programme records on 2026-11-11.
-- Expired GTEC listings are excluded. Institution logos and websites remain blank unless independently verified.
BEGIN;

ALTER TABLE public.universities
  ADD COLUMN IF NOT EXISTS accreditation_status text,
  ADD COLUMN IF NOT EXISTS accreditation_valid_from date,
  ADD COLUMN IF NOT EXISTS accreditation_valid_until date,
  ADD COLUMN IF NOT EXISTS accreditation_source_url text,
  ADD COLUMN IF NOT EXISTS accreditation_checked_at date;

ALTER TABLE public.universities DROP CONSTRAINT IF EXISTS universities_institution_type_check;
ALTER TABLE public.universities ADD CONSTRAINT universities_institution_type_check CHECK (
  institution_type IS NULL OR institution_type IN (
    'Public University', 'Public Technical University', 'Private Chartered University',
    'Private University', 'Other recognized university-level institution',
    'Public College of Education', 'Private College of Education',
    'Public Nurses/Health Training College', 'Private Nurses/Health Training College'
  )
);

CREATE INDEX IF NOT EXISTS universities_accreditation_status_idx
  ON public.universities (accreditation_status, accreditation_valid_until)
  WHERE accreditation_status IS NOT NULL;

INSERT INTO public.universities (
  name, official_name, short_name, slug, city, region, country, website_url, description,
  institution_type, ownership_type, campus_launch_status, is_enabled, is_verified,
  accreditation_status, accreditation_valid_from, accreditation_valid_until,
  accreditation_source_url, accreditation_checked_at
)
SELECT
  roster.name, roster.name, roster.name, roster.slug, roster.city, roster.region, 'Ghana',
  NULL, roster.description, roster.institution_type, roster.ownership_type, 'planned', true, true,
  'active', roster.valid_from::date, roster.valid_until::date, roster.source_url, DATE '2026-11-11'
